    /* 147  LDC CX,MAC */
    ma = MB_CX;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 148  SAC XP   ; XP = XIND*AX + YIND*BX + ZIND*CX + XT */
    ma = MB_XP;
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    /* 149  LAC YT */
    ma = MB_YT;
    w = mb_rd(m, ma);
    m->acc = (int32_t)((uint32_t)w << 16);
    /* 14A  LDA X,IND */
    ma = MB_IND(m, 0);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 14B  LDC AY,MAC */
    ma = MB_AY;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 14C  LDA Y,IND */
    ma = MB_IND(m, 1);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 14D  LDC BY,MAC */
    ma = MB_BY;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 14E  LDA Z,IND */
    ma = MB_IND(m, 2);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 14F  LDC CY,MAC */
    ma = MB_CY;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 150  SAC YP   ; YP = XIND*AY + YIND*BY + ZIND*CY + YT */
    ma = MB_YP;
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    /* 151  LAC ZT */
    ma = MB_ZT;
    w = mb_rd(m, ma);
    m->acc = (int32_t)((uint32_t)w << 16);
    /* 152  LDA X,IND */
    ma = MB_IND(m, 0);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 153  LDC AZ,MAC */
    ma = MB_AZ;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 154  LDA Y,IND */
    ma = MB_IND(m, 1);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 155  LDC BZ,MAC */
    ma = MB_BZ;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 156  LDA Z,IND */
