    /* 1CF  SAC XCS   ; XCS = XSCALE * XSCALE */
    ma = MB_XCS;
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    /* 1D0  LDA XP,CLA */
    ma = MB_XP;
    w = mb_rd(m, ma);
    m->acc = 0;
    m->a = (int16_t)w;
    /* 1D1  LDC XP,MAC */
    ma = MB_XP;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 1D2  SAC XPS   ; XPS = XP * XP */
    ma = MB_XPS;
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    /* 1D3  LDA YP,CLA */
    ma = MB_YP;
    w = mb_rd(m, ma);
    m->acc = 0;
    m->a = (int16_t)w;
    /* 1D4  LDC YP,MAC */
    ma = MB_YP;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 1D5  SAC YPS   ; YPS = YP * YP */
    ma = MB_YPS;
