/* PER2: PC AE (address 2B8) */
void mb_prog_PER2(sw_mbox *m)
{
    uint16_t ma, w;
    (void)ma;
    (void)w;
    /* 2B8  LDA YR,IND */
    ma = MB_IND(m, 0);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 2B9  LDB YP,CLA */
    ma = MB_YP;
    w = mb_rd(m, ma);
    m->acc = 0;
    m->b = (int16_t)w;
    /* 2BA  LDC YT,MAC */
    ma = MB_YT;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 2BB  SAC XS,IND   ; XS,IND=(YR,IND-(-YP))*(YT) */
    ma = MB_IND(m, 2);
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    /* 2BC  LDA ZR,IND */
    ma = MB_IND(m, 1);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 2BD  LDB ZP,CLA */
    ma = MB_ZP;
    w = mb_rd(m, ma);
    m->acc = 0;
    m->b = (int16_t)w;
    /* 2BE  LDC YT,MAC */
    ma = MB_YT;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 2BF  SAC YS,IND,IBC   ; YS,IND=(ZR,IND-(-ZP))*(YT) */
    ma = MB_IND(m, 3);
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    m->bic = (m->bic + 1) & 0x1ff;
    /* 2C0  LDA XR,IND */
    ma = MB_IND(m, 3);
    w = mb_rd(m, ma);
    m->a = (int16_t)w;
    /* 2C1  LDB XP,CLA */
    ma = MB_XP;
    w = mb_rd(m, ma);
    m->acc = 0;
    m->b = (int16_t)w;
    /* 2C2  LDC ONE,MAC */
    ma = MB_ONE;
    w = mb_rd(m, ma);
    mb_mac(m, (int16_t)w);
    /* 2C3  SAC XT,IBC,HALT   ; XT=(XR,IND-(-XP))*ONE */
    ma = MB_XT;
    mb_wr(m, ma, (uint16_t)((uint32_t)m->acc >> 16));
    m->bic = (m->bic + 1) & 0x1ff;
}

